package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="succession_pool_membership_event",uniqueConstraints=@UniqueConstraint(name="uk_succ_membership_event_sequence",columnNames={"agency_id","pool_decision_id","event_sequence"}))
public class SuccessionPoolMembershipEvent extends RspAuditedEntity{
 public enum EventType{ACTIVATED,CORRECTED,EXPIRED,REMOVED,REINSTATED}public enum ResultingStatus{ACTIVE,EXPIRED,REMOVED}
 @Column(name="pool_decision_id",nullable=false,length=36)private String poolDecisionId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="previous_event_id",length=36)private String previousEventId;@Column(name="event_sequence",nullable=false)private int eventSequence;@Enumerated(EnumType.STRING)@Column(name="event_type",nullable=false,length=20)private EventType eventType;@Enumerated(EnumType.STRING)@Column(name="resulting_status",nullable=false,length=20)private ResultingStatus resultingStatus;@Column(name="effective_on",nullable=false)private LocalDate effectiveOn;@Column(name="expires_on")private LocalDate expiresOn;@Column(name="employee_visible_reason",nullable=false,length=4000)private String employeeVisibleReason;@Column(name="restricted_rationale",nullable=false,length=4000)private String restrictedRationale;@Column(name="recorded_by",nullable=false,length=100)private String recordedBy;@Column(name="recorded_at",nullable=false)private Instant recordedAt;
 protected SuccessionPoolMembershipEvent(){}public static SuccessionPoolMembershipEvent activate(String agency,SuccessionPoolDecision decision,String actor,Instant at){if(decision.getOutcome()!=SuccessionPoolDecision.Outcome.INCLUDED)throw new IllegalArgumentException("Only an included decision may activate membership");return new SuccessionPoolMembershipEvent(agency,decision.getId(),decision.getCandidateId(),null,1,EventType.ACTIVATED,ResultingStatus.ACTIVE,decision.getEffectiveFrom(),decision.getExpiresOn(),decision.getEmployeeVisibleReason(),decision.getRestrictedRationale(),actor,at);}
 public SuccessionPoolMembershipEvent transition(EventType type,LocalDate effective,LocalDate expiry,String employeeReason,String restrictedReason,String actor,Instant at){if(type==EventType.ACTIVATED)throw new IllegalArgumentException("Membership is already activated");ResultingStatus next=switch(type){case CORRECTED,REINSTATED->ResultingStatus.ACTIVE;case EXPIRED->ResultingStatus.EXPIRED;case REMOVED->ResultingStatus.REMOVED;default->throw new IllegalArgumentException("Unsupported transition");};if(type==EventType.REINSTATED&&resultingStatus!=ResultingStatus.REMOVED)throw new IllegalStateException("Only removed membership may be reinstated");if((type==EventType.REMOVED||type==EventType.EXPIRED||type==EventType.CORRECTED)&&resultingStatus!=ResultingStatus.ACTIVE)throw new IllegalStateException("Transition requires active membership");if(next==ResultingStatus.ACTIVE&&(expiry==null||expiry.isBefore(effective)))throw new IllegalArgumentException("Active membership requires a valid expiry");return new SuccessionPoolMembershipEvent(getAgencyId(),poolDecisionId,candidateId,getId(),eventSequence+1,type,next,effective,expiry,employeeReason,restrictedReason,actor,at);}
 private SuccessionPoolMembershipEvent(String agency,String decision,String candidate,String previous,int sequence,EventType type,ResultingStatus status,LocalDate effective,LocalDate expiry,String visible,String restricted,String actor,Instant at){super(agency);poolDecisionId=requiredText(decision,"poolDecisionId");candidateId=requiredText(candidate,"candidateId");previousEventId=optionalText(previous);eventSequence=sequence;eventType=type;resultingStatus=status;effectiveOn=java.util.Objects.requireNonNull(effective);expiresOn=expiry;employeeVisibleReason=requiredText(visible,"employeeVisibleReason");restrictedRationale=requiredText(restricted,"restrictedRationale");recordedBy=requiredText(actor,"actor");recordedAt=at;}
 public String getPoolDecisionId(){return poolDecisionId;}public String getCandidateId(){return candidateId;}public String getPreviousEventId(){return previousEventId;}public int getEventSequence(){return eventSequence;}public EventType getEventType(){return eventType;}public ResultingStatus getResultingStatus(){return resultingStatus;}public LocalDate getEffectiveOn(){return effectiveOn;}public LocalDate getExpiresOn(){return expiresOn;}public String getEmployeeVisibleReason(){return employeeVisibleReason;}public String getRestrictedRationale(){return restrictedRationale;}public String getRecordedBy(){return recordedBy;}public Instant getRecordedAt(){return recordedAt;}
}
